<?phpclass ModelCareersCareers extends Model{    public function getAllData(){        $sql = "SELECT * FROM ".DB_PREFIX."wsb_job WHERE status != 0 ";        $query = $this->db->query($sql);       //echo "<pre>"; print_r($query); echo "</pre>";        return $query->rows;    }    public function jobAppliedData($data){        //echo "<pre>"; print_r($data->post); echo"</pre>";die;        if(!empty($data)){            $sql = "INSERT INTO " . DB_PREFIX . "wsb_job_applied SET                job_id = '" . (int)($data->post['job_id']) . "',                name = '" . $this->db->escape($data->post['your_name']) . "',                email = '" . $this->db->escape($data->post['email']) . "',                phone = '" . $this->db->escape($data->post['mobile']) . "',                current_ctc = '" . $this->db->escape($data->post['current_ctc']) . "',                expected_ctc = '" . $this->db->escape($data->post['expected_ctc']) . "',                resume = '" . $this->db->escape($data->files['resume']['name']) . "',                cover_letter = '" . $this->db->escape($data->post['cover_letter']) . "',                ip = '" . $this->db->escape($this->request->getIpAddress). "',                os = '" . $this->db->escape($this->getOS($_SERVER['HTTP_USER_AGENT'])). "',                browser = '" . $this->db->escape($_SERVER['HTTP_USER_AGENT']) . "',                created_date = '" . date('Y-m-d') . "'                ";            //echo "<pre>"; print_r($sql); echo "</pre>"; die;            $this->db->query($sql);        }    }    protected  function getOS($user_agent) {        $os_platform    =   "Unknown OS Platform";        $os_array       =   array(            '/windows nt 10/i'     =>  'Windows 10',            '/windows nt 6.3/i'     =>  'Windows 8.1',            '/windows nt 6.2/i'     =>  'Windows 8',            '/windows nt 6.1/i'     =>  'Windows 7',            '/windows nt 6.0/i'     =>  'Windows Vista',            '/windows nt 5.2/i'     =>  'Windows Server 2003/XP x64',            '/windows nt 5.1/i'     =>  'Windows XP',            '/windows xp/i'         =>  'Windows XP',            '/windows nt 5.0/i'     =>  'Windows 2000',            '/windows me/i'         =>  'Windows ME',            '/win98/i'              =>  'Windows 98',            '/win95/i'              =>  'Windows 95',            '/win16/i'              =>  'Windows 3.11',            '/macintosh|mac os x/i' =>  'Mac OS X',            '/mac_powerpc/i'        =>  'Mac OS 9',            '/linux/i'              =>  'Linux',            '/ubuntu/i'             =>  'Ubuntu',            '/iphone/i'             =>  'iPhone',            '/ipod/i'               =>  'iPod',            '/ipad/i'               =>  'iPad',            '/android/i'            =>  'Android',            '/blackberry/i'         =>  'BlackBerry',            '/webos/i'              =>  'Mobile'        );        foreach ($os_array as $regex => $value) {            if (preg_match($regex, $user_agent)) {                $os_platform    =   $value;            }        }        return $os_platform;    }    public function getPostName($job_id){        $sql = "SELECT wj.title FROM ".DB_PREFIX."wsb_job wj WHERE job_id =".$job_id;        $query = $this->db->query($sql);        //echo "<pre>"; print_r($query); echo "</pre>"; die;        return $query->row['title'];    }}